SELECT jsonb_build_object('version',current_setting('server_version_num'),'systemIdentifier',(SELECT system_identifier::text FROM pg_control_system()),'columns',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated) ORDER BY n.nspname,c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('auth','storage') AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped),'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'sha256',encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex')) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('auth','storage') AND p.prokind IN ('f','p')),'authMigrationVersions',(SELECT jsonb_agg(version::text ORDER BY version::text) FROM auth.schema_migrations),'storageMigrationMetadata',(SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',j->'id','name',j->'name','hash',j->'hash','version',j->'version')) ORDER BY j->>'id') FROM (SELECT to_jsonb(t) j FROM storage.migrations t) s),'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'super',rolsuper,'inherit',rolinherit,'login',rolcanlogin,'bypassRls',rolbypassrls,'createRole',rolcreaterole,'createDb',rolcreatedb) ORDER BY rolname) FROM pg_roles WHERE rolname IN ('postgres','anon','authenticated','service_role','authenticator','supabase_auth_admin','supabase_storage_admin','clinia_document_delivery')),'memberships',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'admin',a.admin_option,'inherit',a.inherit_option,'set',a.set_option) ORDER BY r.rolname,m.rolname) FROM pg_auth_members a JOIN pg_roles r ON r.oid=a.roleid JOIN pg_roles m ON m.oid=a.member WHERE r.rolname='clinia_document_delivery' OR m.rolname='clinia_document_delivery'));
